Add-Type -AssemblyName System.Drawing
$out=Split-Path -Parent $MyInvocation.MyCommand.Path;$c=Get-Content -Raw -Encoding UTF8 (Join-Path $out 'korean-architecture-content.json')|ConvertFrom-Json
$font=New-Object System.Drawing.Font('Malgun Gothic',12);$small=New-Object System.Drawing.Font('Malgun Gothic',10);$label=New-Object System.Drawing.Font('Malgun Gothic',14,[System.Drawing.FontStyle]::Bold);$title=New-Object System.Drawing.Font('Malgun Gothic',27,[System.Drawing.FontStyle]::Bold);$ink=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(20,30,45));$green=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(232,247,235));$green2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(28,112,54),2);$orange=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(255,243,229));$orange2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(222,92,19),2);$blue=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(235,242,255));$blue2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(38,80,190),2);$purple=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(244,238,255));$purple2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(88,43,180),2);$gray=New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(248,250,252));$gray2=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(90,105,125),2);$line=New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(55,65,81),2)
function B($g,$x,$y,$w,$h,$head,$body,$fill,$stroke){$g.FillRectangle($fill,$x,$y,$w,$h);$g.DrawRectangle($stroke,$x,$y,$w,$h);$s=[System.Drawing.StringFormat]::new();$s.Alignment='Center';$s.LineAlignment='Near';$g.DrawString($head,$label,$ink,[System.Drawing.RectangleF]::new($x+8,$y+10,$w-16,32),$s);$g.DrawString($body,$small,$ink,[System.Drawing.RectangleF]::new($x+14,$y+50,$w-28,$h-58),$s)}
function A($g,$x1,$y1,$x2,$y2,$t=''){$g.DrawLine($line,$x1,$y1,$x2,$y2);$g.FillPolygon($ink,@([System.Drawing.Point]::new($x2,$y2),[System.Drawing.Point]::new($x2-10,$y2-5),[System.Drawing.Point]::new($x2-10,$y2+5)));if($t){$s=[System.Drawing.StringFormat]::new();$s.Alignment='Center';$g.DrawString($t,$small,$ink,[System.Drawing.RectangleF]::new(($x1+$x2)/2-70,($y1+$y2)/2-20,140,38),$s)}}
function C($w,$h){$b=New-Object System.Drawing.Bitmap($w,$h);$g=[System.Drawing.Graphics]::FromImage($b);$g.Clear([System.Drawing.Color]::White);$g.SmoothingMode='AntiAlias';return @($b,$g)}
function S($b,$g,$n){$g.Dispose();$b.Save((Join-Path $out $n),[System.Drawing.Imaging.ImageFormat]::Png);$b.Dispose()}

$p=C 2100 1250;$b=$p[0];$g=$p[1];$g.DrawString('1. Main Architecture',$title,$ink,60,25);$g.DrawString($c.subtitle,$font,$ink,70,75);B $g 50 250 250 300 $c.user.head $c.user.body $gray $gray2;B $g 350 250 280 300 $c.frontend.head $c.frontend.body $green $green2;A $g 300 400 350 400 'input';$g.DrawRectangle($green2,680,130,850,980);$g.DrawString('Main API Server - Node.js HTTP Server',$label,$ink,900,150);B $g 720 210 770 135 $c.routes.head $c.routes.body $gray $green2;B $g 720 375 770 145 $c.validation.head $c.validation.body $green $green2;B $g 720 550 770 170 $c.orchestrator.head $c.orchestrator.body $green $green2;A $g 1105 345 1105 375 'request';A $g 1105 520 1105 550 'validated';B $g 720 770 360 210 $c.knowledge.head $c.knowledge.body $blue $blue2;B $g 1130 770 360 210 $c.data.head $c.data.body $blue $blue2;A $g 900 720 900 770 'lookup';A $g 1080 875 1130 875 'read';B $g 720 1010 360 210 $c.agents.head $c.agents.body $orange $orange2;B $g 1130 1010 360 210 $c.model.head $c.model.body $orange $orange2;A $g 1250 720 1250 1010 'generate';A $g 1080 1110 1130 1110 'call';B $g 1600 180 430 230 $c.a2a.head $c.a2a.body $purple $purple2;B $g 1600 470 430 230 $c.ops.head $c.ops.body $purple $purple2;B $g 1600 760 430 230 $c.response.head $c.response.body $green $green2;A $g 1530 300 1600 300 'external';A $g 1530 800 1600 850 'merge';S $b $g 'main-architecture-ko.png'

$p=C 2450 1450;$b=$p[0];$g=$p[1];$g.DrawString('2. Cat / Catalog Architecture',$title,$ink,650,25);$g.DrawString('Comparison layout based on the reference image',$font,$ink,820,75);B $g 30 360 210 430 $c.user.head $c.user.body $gray $gray2;B $g 275 360 240 430 $c.frontend.head $c.frontend.body $green $green2;A $g 240 560 275 560 'question';$g.DrawRectangle($green2,550,120,650,1120);$g.DrawString('Cat API - Catalog Q&A Server',$label,$ink,720,145);B $g 580 205 590 135 $c.validation.head $c.validation.body $green $green2;B $g 580 365 590 165 'Cat Orchestrator - catalog mode' $c.orchestrator.body $green $green2;B $g 580 560 590 180 $c.knowledge.head $c.knowledge.body $blue $blue2;B $g 580 770 590 180 $c.agents.head $c.agents.body $orange $orange2;B $g 580 980 590 180 $c.model.head $c.model.body $orange $orange2;A $g 875 340 875 365 'validate';A $g 875 530 875 560 'lookup';A $g 875 740 875 770 'agent';A $g 875 950 875 980 'model';B $g 1280 170 430 260 'Catalog Knowledge Layer' $c.data.body $blue $blue2;B $g 1280 500 430 260 'Specialized Agents' $c.agents.body $orange $orange2;B $g 1280 830 430 260 'Model Adapter' $c.model.body $orange $orange2;A $g 1200 650 1280 300 'knowledge';A $g 1200 850 1280 630 'agent';A $g 1200 1050 1280 960 'generate';B $g 1780 170 570 300 $c.a2a.head $c.a2a.body $purple $purple2;B $g 1780 550 570 300 $c.ops.head $c.ops.body $purple $purple2;B $g 1780 930 570 250 $c.response.head $c.response.body $green $green2;A $g 1710 300 1780 300 'external';A $g 1710 680 1780 680 'operations';A $g 1710 1010 1780 1050 'response';$g.DrawRectangle($blue2,30,1230,2320,150);$g.DrawString('Cat flow: question -> catalog mode -> knowledge search -> sourceRef -> answer + sources',$font,$ink,70,1280);S $b $g 'cat-architecture-ko.png'

$p=C 2350 1350;$b=$p[0];$g=$p[1];$g.DrawString('3. Main + Cat + Video + Development + WorkMate',$title,$ink,330,25);$g.DrawString('Main distributes requests through shared contracts and merges service results',$font,$ink,760,75);B $g 40 450 240 300 $c.user.head $c.user.body $gray $gray2;B $g 350 350 400 500 $c.orchestrator.head $c.orchestrator.body $green $green2;A $g 280 600 350 600 'request';B $g 850 150 400 220 $c.cat.head $c.cat.body $blue $blue2;B $g 850 420 400 220 $c.video.head $c.video.body $gray $gray2;B $g 850 690 400 220 $c.development.head $c.development.body $gray $gray2;B $g 850 960 400 220 $c.workmate.head $c.workmate.body $gray $gray2;A $g 750 470 850 260 'catalog';A $g 750 560 850 530 'video';A $g 750 650 850 800 'dev-guide';A $g 750 740 850 1070 'workContext';B $g 1370 150 390 220 $c.data.head $c.data.body $blue $blue2;B $g 1370 420 390 220 $c.response.head $c.response.body $green $green2;B $g 1370 690 390 220 $c.model.head $c.model.body $orange $orange2;B $g 1370 960 390 220 $c.a2a.head $c.a2a.body $purple $purple2;A $g 1250 260 1370 260 'data';A $g 1250 530 1370 530 'result';A $g 1250 800 1370 800 'model';A $g 1250 1070 1370 1070 'A2A';B $g 1850 410 440 380 $c.ops.head $c.ops.body $purple $purple2;A $g 1760 530 1850 530 'health metrics';$g.DrawRectangle($blue2,40,1190,2250,100);$g.DrawString('Integration rule: requestId + mode + context + evidence are shared across all services',$font,$ink,75,1235);S $b $g 'main-connected-services-ko.png';Write-Output 'Created three files.'
